import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/UbicacionRedes.css';

const UbicacionRedes = () => {
  const navigate = useNavigate();
  useEffect(() => {
    document.body.style.backgroundImage = "url('/fondo-naranja.png')";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundRepeat = "no-repeat";
    document.body.style.minHeight = "100vh";
    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundRepeat = "";
      document.body.style.minHeight = "";
    };
  }, []);
  return (
    <div className="ubicacion-container">
      <button onClick={() => navigate(-1)} className="servicios-btn" style={{marginBottom: '1.5rem'}}>
        Regresar
      </button>
      <h2 className="ubicacion-title">Ubicación y Redes Sociales</h2>
      <div className="ubicacion-info">
        <p><strong>Dirección:</strong> Calle #29 -1, Monteria, Colombia</p>
        <p><strong>Teléfono:</strong> +57 123 456 7890</p>
        <p><strong>Email:</strong> contacto@phgsoluciones.com</p>
      </div>
      <div className="ubicacion-redes">
        <a href="https://facebook.com/phgsoluciones" target="_blank" rel="noopener noreferrer">Facebook</a>
        <a href="https://instagram.com/phgsoluciones" target="_blank" rel="noopener noreferrer">Instagram</a>
        <a href="https://wa.me/571234567890" target="_blank" rel="noopener noreferrer">WhatsApp</a>
      </div>
      <div className="ubicacion-mapa">
        <iframe
          title="Ubicación PHG"
          src="https://www.google.com/maps?q=calle+29+-1&output=embed"
          width="100%"
          height="250"
          style={{ border: 0 }}
          allowFullScreen=""
          loading="lazy"
        ></iframe>
      </div>
    </div>
  );
};

export default UbicacionRedes;
